// Validate and extract contract_id from webhook
const input = $input.all()[0].json;
const contractId = input.contract_id || input.body?.contract_id || input.query?.contract_id || (input.body && typeof input.body === 'string' ? JSON.parse(input.body).contract_id : null);

if (!contractId || contractId === '' || contractId === 'null' || contractId === null || contractId === undefined) {
  throw new Error('contract_id is required. Received: ' + JSON.stringify(input));
}

return {
  json: {
    contract_id: String(contractId).trim(),
    execution_id: $execution.id || `exec_${Date.now()}`,
    workflow_name: 'Contract Approval Multi-Level'
  }
};

// Log error: Contract not found
const contractId = $node['Validate Contract ID'].json.contract_id;

return {
  json: {
    success: false,
    message: `Contract with ID ${contractId} not found`,
    contract_id: contractId,
    error: 'CONTRACT_NOT_FOUND'
  }
};

// Format data for approval workflow using database function
const contract = $node['Get Contract Details'].json || {};
const workflowLevels = $node['Get Workflow Levels'].json || [];
const executionId = $node['Validate Contract ID'].json.execution_id;

// Get total_steps dynamically from workflow_levels
const totalSteps = Array.isArray(workflowLevels) ? workflowLevels.length : 0;

// Get first level info
const firstLevel = Array.isArray(workflowLevels) && workflowLevels.length > 0 ? workflowLevels[0] : null;

// Validate user ID
function getValidUserId(...ids) {
  for (const id of ids) {
    if (id !== null && id !== undefined && id !== 0 && id !== '0' && id !== '') {
      const numId = Number(id);
      if (!isNaN(numId) && numId > 0) {
        return numId;
      }
    }
  }
  return null;
}

const userId = getValidUserId(contract.creator_user_id, contract.created_by_id);

return {
  json: {
    // For database function
    p_contract_id: contract.id,
    p_created_by_id: userId,
    // For workflow data
    document_type: 'contract',
    document_id: contract.id,
    workflow_name: `Contract Approval - ${contract.contract_number || 'N/A'}`,
    total_steps: totalSteps || 1,
    current_step: 1,
    created_by_id: userId,
    assigned_to_id: userId,
    status: 'in_progress',
    // Contract data
    contract_id: contract.id,
    contract_number: contract.contract_number,
    creator_id: userId,
    creator_name: contract.creator_name,
    creator_email: contract.creator_email,
    total_amount: contract.total_amount,
    work_id: contract.work_id,
    translator_id: contract.translator_id,
    // Workflow levels data
    workflow_levels: workflowLevels,
    current_level: firstLevel,
    current_level_number: firstLevel ? firstLevel.level_number : 1,
    current_level_role: firstLevel ? firstLevel.role_id : null,
    current_level_name: firstLevel ? firstLevel.level_name : 'Level 1',
    timeout_hours: firstLevel ? firstLevel.timeout_hours : 48,
    // Execution tracking
    execution_id: executionId,
    workflow_name: 'Contract Approval Multi-Level'
  }
};

// Generate approval token and format data for notifications
const workflow = $node['Create Approval Workflow'].json || {};
const approver = $node['Get Current Level Approver'].json || {};
const contractData = $node['Format Approval Data'].json || {};

// Generate unique token
const token = `token_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Calculate expiry date
const timeoutHours = contractData.timeout_hours || 48;
const expiryDate = new Date();
expiryDate.setHours(expiryDate.getHours() + timeoutHours);

return {
  json: {
    // Token data
    approval_token: token,
    token_expiry: expiryDate.toISOString(),
    // Workflow data
    workflow_id: workflow.workflow_id || workflow.id,
    approver_id: approver.user_id || approver.id,
    approver_email: approver.email || '',
    approver_name: approver.full_name || approver.name || 'Unknown',
    approver_username: approver.username || approver.email?.split('@')[0] || 'user',
    step_number: contractData.current_step || 1,
    // Contract data
    contract_id: contractData.contract_id,
    contract_number: contractData.contract_number,
    creator_name: contractData.creator_name,
    creator_email: contractData.creator_email,
    total_amount: contractData.total_amount,
    // Level data
    level: contractData.current_level_number,
    level_name: contractData.current_level_name,
    level_role: contractData.current_level_role,
    timeout_hours: timeoutHours,
    // URLs
    approve_url: `http://localhost:5678/webhook/contract-approval-decision?token=${token}&decision=approved`,
    reject_url: `http://localhost:5678/webhook/contract-approval-decision?token=${token}&decision=rejected`,
    // Execution tracking
    execution_id: contractData.execution_id
  }
};

// Format Mattermost message for contract approval
const data = $node['Generate Approval Token'].json || {};

return {
  json: {
    text: `📄 **Contract Approval Required**\n\nA new contract requires your approval at **${data.level_name || 'Level 1'}**.`,
    channel: '#contracts-approvals',
    attachments: [
      {
        color: '#4ECDC4',
        title: `Contract ${data.contract_number || 'N/A'}`,
        text: 'Please review and take action on this contract approval request.',
        fields: [
          {
            short: true,
            title: 'Contract Number',
            value: data.contract_number || 'N/A'
          },
          {
            short: true,
            title: 'Amount',
            value: data.total_amount ? new Intl.NumberFormat('vi-VN', {style: 'currency', currency: 'VND'}).format(data.total_amount) : 'N/A'
          },
          {
            short: true,
            title: 'Created by',
            value: data.creator_name || 'Unknown'
          },
          {
            short: true,
            title: 'Approver',
            value: `@${data.approver_username || 'manager'}`
          },
          {
            short: true,
            title: 'Level',
            value: `${data.level_name || 'Level 1'} (Level ${data.level || 1})`
          },
          {
            short: true,
            title: 'Expires in',
            value: `${data.timeout_hours || 48} hours`
          }
        ],
        actions: [
          {
            name: '✅ Approve',
            integration: {
              url: data.approve_url,
              context: {
                token: data.approval_token,
                decision: 'approved'
              }
            }
          },
          {
            name: '❌ Reject',
            integration: {
              url: data.reject_url,
              context: {
                token: data.approval_token,
                decision: 'rejected'
              }
            }
          }
        ],
        footer: 'OrientClassicsManager',
        ts: Math.floor(Date.now() / 1000)
      }
    ]
  }
};

// Format Zalo notification (using HTTP Request)
// Note: Zalo requires API integration - this is a template
const data = $node['Generate Approval Token'].json || {};

// Zalo message format
const zaloMessage = `📄 Yêu cầu phê duyệt hợp đồng\n\n` +
  `Số hợp đồng: ${data.contract_number || 'N/A'}\n` +
  `Người tạo: ${data.creator_name || 'Unknown'}\n` +
  `Giá trị: ${data.total_amount ? new Intl.NumberFormat('vi-VN', {style: 'currency', currency: 'VND'}).format(data.total_amount) : 'N/A'}\n` +
  `Cấp phê duyệt: ${data.level_name || 'Level 1'}\n` +
  `Hết hạn sau: ${data.timeout_hours || 48} giờ\n\n` +
  `Vui lòng xem chi tiết và phê duyệt tại email hoặc Mattermost.`;

return {
  json: {
    // Zalo API endpoint (configure based on your Zalo integration)
    url: 'https://openapi.zalo.me/v2.0/oa/message',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'access_token': '{{ $vars.ZALO_ACCESS_TOKEN }}' // Set in N8N variables
    },
    body: {
      recipient: {
        user_id: data.approver_zalo_id || '' // Need to map user to Zalo ID
      },
      message: {
        text: zaloMessage
      }
    },
    // Keep original data
    ...data,
    zalo_message: zaloMessage
  }
};

// Extract token and decision from query parameters
const input = $input.all()[0].json;
const token = input.query?.token || input.token || null;
const decision = input.query?.decision || input.decision || null;

if (!token || !decision) {
  throw new Error('Token and decision are required. Received: ' + JSON.stringify(input));
}

if (!['approved', 'rejected'].includes(decision.toLowerCase())) {
  throw new Error('Decision must be "approved" or "rejected". Received: ' + decision);
}

return {
  json: {
    token: token,
    decision: decision.toLowerCase(),
    execution_id: $execution.id || `exec_${Date.now()}`
  }
};

// Format data for next level approval
const workflowData = $node['Process Approval Decision'].json || {};
const nextLevelData = $node['Get Next Level Info'].json || {};

return {
  json: {
    workflow_id: workflowData.workflow_id,
    current_step: nextLevelData.next_level_number,
    current_level_number: nextLevelData.next_level_number,
    current_level_name: nextLevelData.next_level_name,
    current_level_role: nextLevelData.next_level_role_id,
    timeout_hours: nextLevelData.next_level_timeout || 48,
    contract_id: workflowData.document_id,
    contract_number: workflowData.contract_number || 'N/A',
    execution_id: $node['Validate Decision Input'].json.execution_id
  }
};

// Generate token for next level (reuse logic from first level)
const workflow = $node['Update Workflow Step'].json || {};
const approver = $node['Get Next Level Approver'].json || {};
const levelData = $node['Format Next Level Data'].json || {};

// Generate unique token
const token = `token_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Calculate expiry date
const timeoutHours = levelData.timeout_hours || 48;
const expiryDate = new Date();
expiryDate.setHours(expiryDate.getHours() + timeoutHours);

return {
  json: {
    approval_token: token,
    token_expiry: expiryDate.toISOString(),
    workflow_id: workflow.id || workflow.workflow_id,
    approver_id: approver.user_id || approver.id,
    approver_email: approver.email || '',
    approver_name: approver.full_name || approver.name || 'Unknown',
    approver_username: approver.username || approver.email?.split('@')[0] || 'user',
    step_number: levelData.current_step,
    contract_id: levelData.contract_id,
    contract_number: levelData.contract_number,
    level: levelData.current_level_number,
    level_name: levelData.current_level_name,
    level_role: levelData.current_level_role,
    timeout_hours: timeoutHours,
    approve_url: `http://localhost:5678/webhook/contract-approval-decision?token=${token}&decision=approved`,
    reject_url: `http://localhost:5678/webhook/contract-approval-decision?token=${token}&decision=rejected`,
    execution_id: levelData.execution_id
  }
};

// Format email for next level (reuse email formatting logic)
const data = $node['Generate Next Level Token'].json || {};

const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #333; border-bottom: 2px solid #4ECDC4; padding-bottom: 10px;">📄 Contract Approval - Next Level</h2>
  <p>Dear ${data.approver_name},</p>
  <p>The contract <strong>${data.contract_number}</strong> has been approved at the previous level and now requires your approval at <strong>${data.level_name}</strong>.</p>
  <div style="text-align: center; margin: 30px 0;">
    <a href="${data.approve_url}" style="background-color: #4CAF50; color: white; padding: 14px 28px; text-decoration: none; border-radius: 5px; margin-right: 15px; display: inline-block; font-weight: bold;">✅ Approve</a>
    <a href="${data.reject_url}" style="background-color: #f44336; color: white; padding: 14px 28px; text-decoration: none; border-radius: 5px; display: inline-block; font-weight: bold;">❌ Reject</a>
  </div>
</div>
`;

return {
  json: {
    to: data.approver_email,
    subject: `📄 Contract Approval - Level ${data.level}: ${data.contract_number}`,
    html: emailHtml,
    ...data
  }
};

// Format Mattermost for next level
const data = $node['Generate Next Level Token'].json || {};

return {
  json: {
    text: `📄 **Contract Approved at Previous Level**\n\nContract ${data.contract_number} has been approved and now requires your approval at **${data.level_name}**.`,
    channel: '#contracts-approvals',
    attachments: [
      {
        color: '#4ECDC4',
        title: `Contract ${data.contract_number} - Level ${data.level}`,
        fields: [
          { short: true, title: 'Level', value: data.level_name },
          { short: true, title: 'Approver', value: `@${data.approver_username}` }
        ],
        actions: [
          { name: '✅ Approve', integration: { url: data.approve_url } },
          { name: '❌ Reject', integration: { url: data.reject_url } }
        ]
      }
    ]
  }
};

// Format final approval notifications
const workflow = $node['Process Approval Decision'].json || {};
const contract = $node['Final Approval - Update Contract'].json || {};

return {
  json: {
    contract_id: contract.id,
    contract_number: contract.contract_number || workflow.contract_number,
    creator_email: workflow.creator_email,
    creator_name: workflow.creator_name,
    total_amount: contract.total_amount || workflow.total_amount,
    // Email data
    email_to: workflow.creator_email,
    email_subject: `✅ Contract Approved: ${contract.contract_number || 'N/A'}`,
    email_html: `<h2>Contract Approved</h2><p>Your contract ${contract.contract_number} has been fully approved!</p>`,
    // Mattermost data
    mattermost_channel: '#contracts-approvals',
    mattermost_text: `✅ **Contract Fully Approved**\n\nContract ${contract.contract_number} has completed all approval levels.`,
    // Zalo data
    zalo_message: `✅ Hợp đồng ${contract.contract_number} đã được phê duyệt hoàn toàn.`
  }
};

// Format rejection notifications
const workflow = $node['Process Approval Decision'].json || {};

return {
  json: {
    contract_number: workflow.contract_number,
    creator_email: workflow.creator_email,
    creator_name: workflow.creator_name,
    email_to: workflow.creator_email,
    email_subject: `❌ Contract Rejected: ${workflow.contract_number}`,
    email_html: `<h2>Contract Rejected</h2><p>Your contract ${workflow.contract_number} has been rejected.</p>`,
    mattermost_channel: '#contracts-approvals',
    mattermost_text: `❌ **Contract Rejected**\n\nContract ${workflow.contract_number} has been rejected.`
  }
};
